701→    // the backend response (cache keeps rich segments / streaming data).
702→    let finalMsgs = msgs;
703→    if (incomingConversationId) {
704→      const cached = messagesCacheRef.current.get(incomingConversationId);
705→      if (cached && cached.length > 0 && cached.length >= msgs.length) {
706→        finalMsgs = cached;
707→      }
708→      // Clear used cache entry so stale data doesn't persist forever
709→      messagesCacheRef.current.delete(incomingConversationId);
710→    }
711→
712→    // Capture ref values NOW — React 18 batching may defer the updater
713→    // function below until after the ref resets at the bottom of this
714→    // function, so reading refs inside the updater would see empty values.
715→    const capturedTextBuffer = textBufferRef.current;
716→    const capturedAssistantId = assistantIdRef.current;
717→    const capturedSegments = [...segmentsRef.current];
718→    const capturedCurrentText = currentTextRef.current;
719→    const capturedPhase = phaseRef.current;
720→
721→    // Save current messages to cache before replacing them.
722→    setMessages(prev => {
723→      console.log('[CONV-DEBUG] loadMessages setMessages updater', { outgoing, prevLen: prev.length, finalMsgsLen: finalMsgs.length, prevMsgs: prev.map(m => ({ id: m.id.slice(0,8), role: m.role, isStreaming: m.isStreaming, contentLen: m.content.length })) });
724→      if (outgoing && prev.length > 0) {
725→        const pendingText = capturedTextBuffer;
726→        const aId = capturedAssistantId;
727→
728→        // Build finalized segments including any unflushed text
729→        let finalSegments = [...capturedSegments];
