761→    textBufferRef.current = '';
762→    currentTextRef.current = '';
763→    segmentsRef.current = [];
764→    assistantIdRef.current = '';
765→    phaseRef.current = 'thinking';
766→    sessionIdRef.current = null;
767→    pendingHistoryRef.current = null;
768→  }, []);
769→
770→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
771→    console.log('[CONV-DEBUG] clearMessages called', { outgoingConversationId, streamConvRef: streamConversationIdRef.current, cacheKeys: [...messagesCacheRef.current.keys()], isStreaming });
772→    ++streamGenerationRef.current;
773→    const outgoing = outgoingConversationId || streamConversationIdRef.current;
774→    activeConversationIdRef.current = null;
775→    if (abortRef.current) {
776→      abortRef.current.abort();
777→      abortRef.current = null;
778→    }
779→    if (flushTimerRef.current) {
780→      clearTimeout(flushTimerRef.current);
